    w_local, w_parent, w_root = weights
    if own_sim >= self.cluster_sync_sim_threshold:
        w_local = 0.0
    else:
        w_parent = 0.0
    total = w_local + w_parent + w_root
    if total <= 1e-12:
        return (0.0, 0.0, 1.0)
    return (w_local / total, w_parent / total, w_root / total)

