def _scalar_median(v: torch.Tensor) -> torch.Tensor:
    """Median of a 1-D tensor via sort. torch.median is avoided because the
    dim-reduced variant returns an empty tensor on some accelerators (DirectML)."""
    s = torch.sort(v).values
    n = s.size(0)
    if n % 2 == 1:
        return s[n // 2]
    return 0.5 * (s[n // 2 - 1] + s[n // 2])


def coordinate_median(stack: torch.Tensor) -> torch.Tensor:
    """Coordinate-wise median over dim 0 of a [N, D] stack.

