def bound_update_norms(stacked: torch.Tensor, k: float) -> torch.Tensor:
    """Clamp each update's norm to k * median norm (row-wise rescale).

    Neutralizes magnitude-inflation attacks before trust-weighted summation;
    direction-preserving, so downstream cosine statistics are unchanged.
    """
    if k is None or k <= 0:
        return stacked
    norms = stacked.norm(dim=1)
    scale = (k * _scalar_median(norms) / norms).clamp(max=1.0)
    return stacked * scale.unsqueeze(1)

def _scalar_median(v: torch.Tensor) -> torch.Tensor:
    """Median of a 1-D tensor via sort. torch.median is avoided because the
    dim-reduced variant returns an empty tensor on some accelerators (DirectML)."""
    s = torch.sort(v).values
    n = s.size(0)
    if n % 2 == 1:
        return s[n // 2]
    return 0.5 * (s[n // 2 - 1] + s[n // 2])


